// Reliable structured-output extraction with tool-as-extractor + Zod + retry.
import Anthropic from '@anthropic-ai/sdk';
import { z } from 'zod';
import { zodToJsonSchema } from 'zod-to-json-schema';

export async function extractStructured<S extends z.ZodTypeAny>(
  client: Anthropic,
  input: string,
  schema: S,
  systemPrompt: string,
  maxRetries = 2,
): Promise<z.infer<S>> {
  const toolName = 'emit_result';
  const inputSchema = zodToJsonSchema(schema, { target: 'openApi3' }) as Anthropic.Tool.InputSchema;
  const messages: Anthropic.MessageParam[] = [{ role: 'user', content: input }];

  for (let attempt = 0; attempt <= maxRetries; attempt++) {
    const res = await client.messages.create({
      model: 'claude-sonnet-4-5',
      max_tokens: 1024,
      system: systemPrompt,
      tools: [{ name: toolName, description: 'Emit the extraction result.', input_schema: inputSchema }],
      tool_choice: { type: 'tool', name: toolName },
      messages,
    });
    const tu = res.content.find(b => b.type === 'tool_use');
    if (!tu || tu.type !== 'tool_use') {
      throw new Error('Model failed to emit a tool call.');
    }
    const parsed = schema.safeParse(tu.input);
    if (parsed.success) return parsed.data;

    // Retry with the error in context.
    messages.push({ role: 'assistant', content: res.content });
    messages.push({
      role: 'user',
      content: `Validation failed: ${parsed.error.message}. Emit a corrected ${toolName} call.`,
    });
  }
  throw new Error('extractStructured exceeded retries.');
}
